values ('dialog_fq_iron_051', 'fq_iron_051', 'npc_warlord_steele', 'greeting', '[{"id": "greeting", "text": "War doesn''t wait, Soldier. The Soul Fragmenter threat has escalated", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "A thousand recruits walked through the Bastion gates. A fraction lasted their first week. You''re still standing. Prove there''s more iron in your blood.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Graveyard Recovery: Witness at the Ridge 03. In Cradle Expanse: Defeat 8 AETHEL_ABYSSAL_REAVER. Hold the line and report the condition of the route when the work is done.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 377)
