values ('dialog_fq_merid_028', 'fq_merid_028', 'npc_don_mox', 'greeting', '[{"id": "greeting", "text": "Come in. Business has been good — but it could be better. Leviathans have migrated into the Storm Belt", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Port Meridian handles more cargo in a day than the Concordium''s entire logistics division. When something threatens that, we don''t write reports — we pay people to remove threats.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Jungle Ledger: A Narrow Passage 02. In Black Dock Market: Defeat 1 BLACK_DOCK_ENFORCER. The contract pays for a verified result. Keep the route in mind; that''s where the real value sits.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 454)
